interface AudioProps {
	/**
	 * Same shape as Image, but the accepted values are narrower: remote HTTPS addresses do not play
	 * here. `asset('https://...')` still builds, but the trusted host does not resolve it to sound, so
	 * no request is ever sent. Reason: an image is fetched once and drawn, and failures fold into a
	 * placeholder. Sound keeps flowing, so range requests, buffering, abort and resume all become a
	 * conversation with the remote host. A single IP-masking proxy would not fold that into one step,
	 * and opening that surface is not a decision of this slice.
	 */
	source: AssetRef;
	/**
	 * Whether sound is wanted, not whether it is playing now. Browsers block sound until the user has
	 * interacted with the page. That is normal platform policy, not an error, so `playing={true}` does
	 * not guarantee sound: the host remembers the wish and starts when it is allowed. Defaults to
	 * `false`.
	 */
	playing?: boolean;
	/**
	 * When the sound ends, it starts over from the beginning. Defaults to `false`; then the end is
	 * reported by `onEnded`.
	 */
	loop?: boolean;
	/**
	 * Between 0 and 1, finite. Defaults to 1. Out-of-range values are rejected, not silently clamped.
	 * Clamping `volume={5}` to 1 would make authors believe their value is used, and the
	 * misunderstanding would surface later in computed values. Rejecting there is more honest (the
	 * same decision as `asset()` not trimming whitespace).
	 */
	volume?: number;
	/** Mutes the sound. A separate axis from `volume`: it mutes while remembering the level. */
	muted?: boolean;
	/**
	 * Changing this value rewinds to the beginning. A name is needed because `playing` cannot express
	 * it: on a second press of a sound effect, `playing` is already true, the commit has no change,
	 * and nothing plays. It only rewinds; it does not change whether the sound plays. The value is a
	 * string or number because it crosses the wire, and object identity does not survive that
	 * boundary.
	 */
	restartKey?: string | number;
	/**
	 * Called when playback has finished. Not called while `loop` is set: calling it per cycle would
	 * turn 'ended' into 'went around once', and handling attached to repeating music would run every
	 * cycle. It does not change state: the host never sets `playing` to false on the author's behalf.
	 * To play again, change `restartKey`.
	 */
	onEnded?: () => void | Promise<void>;
	/**
	 * Accepts no children, enforced by the type. Sound is played, not contained, so there is no place
	 * to draw children. Drawing them elsewhere would split what the author wrote from the screen.
	 */
	children?: never;
}

interface ButtonProps extends RuntimeChildren, RuntimePressable {
	/** Visual hierarchy. Adding a value means changing both renderers together. */
	tone?: "primary" | "secondary" | "ghost";
}

interface ImageProps extends RuntimeTransitionable {
	/**
	 * What to draw: an asset reference, not a plain string. Passing through `asset()` is the author's
	 * explicit declaration that the string is an image reference, and a deterministic check runs there
	 * (see asset.ts). Plain strings are still rejected even though remote URLs are now accepted: what
	 * widened is the input to `asset()`, not this prop's type. Which bytes a reference points to is
	 * answered by the trusted host. This package does no lookup, authorization, or caching.
	 */
	source: AssetRef;
	/** Screen-reader label. Omit it for decorative images. */
	alt?: string;
	style?: RuntimeStyle;
	fit?: "cover" | "contain" | "fill";
}

interface PersistentStateDefinition<T> {
	/**
	 * Brand of this lifetime.
	 *
	 * There is no alias such as `type PersistentStateDefinition<T> = StoryStateDefinition<T>`. With an
	 * alias, each hook would accept the other's definition, and a screen would silently read a value
	 * from the wrong lifetime.
	 */
	readonly [RUNTIME_PERSISTENT_STATE]: true;
	readonly key: string;
	readonly version: number;
	readonly initial: T;
	readonly migrate: PersistentStateMigration<T> | null;
}

interface PressableProps
	extends RuntimeChildren,
		RuntimePressable,
		RuntimeTransitionable {
	style?: RuntimeStyle;
}

interface ProgressProps {
	/** 0 to 1. If absent, progress is unbounded (indeterminate, an endless animation). */
	value?: number;
	style?: { width?: RuntimeLength };
}

declare const RUNTIME_GENERATION_LIMITS = Object.freeze({
	maxMessages: 100,
	maxMessageCharacters: 32_768,
	maxInstructionsCharacters: 32_768,
	maxTotalCharacters: 262_144,
	maxOutputCharacters: 16_000,
	defaultOutputCharacters: 4_000,
});

interface RowProps extends RuntimeChildren, RuntimeTransitionable {
	gap?: number;
	style?: RuntimeStyle;
}

type RuntimeComponent<TProps = Record<never, never>> = (
	props: TProps,
) => RuntimeNode;

interface RuntimeElement<TType = unknown, TProps = unknown> {
	readonly $$typeof: typeof RUNTIME_ELEMENT;
	readonly type: TType;
	readonly props: TProps;
	readonly key: string | number | null;
}

declare class RuntimeError extends Error {
	readonly code: RuntimeErrorCode;
	constructor(code: RuntimeErrorCode, message: string);
}

interface RuntimeGenerationRequest {
	messages: readonly RuntimeGenerationMessage[];
	instructions?: string;
	/**
	 * Upper-bound hint for answer length, in characters. The host converts it to its own unit and
	 * truncates to its own cap; tokenizers belong to the host, so this contract never says 'token'.
	 */
	maxOutputCharacters?: number;
}

interface RuntimeHostComponent<TProps> {
	(props: TProps): RuntimeNode;
	readonly [RUNTIME_HOST]: RuntimeHostKind;
}

interface RuntimePressable {
	onPress?: () => void | Promise<void>;
	disabled?: boolean;
}

interface RuntimeScrollController {
	scrollToStart(): void;
	/**
	 * Scroll to the end of the content. If the list has just grown, this is the end after the growth.
	 */
	scrollToEnd(): void;
	scrollTo(options: RuntimeScrollTo): void;
}

interface RuntimeScrollTo {
	/**
	 * Distance from the start of the content, in the same unit as style lengths (CSS pixels on web,
	 * points on native). The axis is set by the ScrollView's `horizontal`: top-down for vertical,
	 * start edge for horizontal. Values beyond the content end are clamped by the platform, not by
	 * this package.
	 */
	offset: number;
}

interface RuntimeStyle {
	width?: RuntimeLength;
	height?: RuntimeLength;
	/**
	 * The size bounds are one set of four. `width` alone cannot express 'as wide as the content, but
	 * never beyond a limit'. A speech bubble has that shape, and a fixed `width: 86%` makes even a
	 * one-word line take the full width. The four are opened together because widening this axis is a
	 * version bump. Opening them one at a time would pay the same cost four times. They have the same
	 * names and meanings on both platforms (CSS min-width, RN minWidth). Values follow `width`: a
	 * number or a percentage.
	 */
	minWidth?: RuntimeLength;
	maxWidth?: RuntimeLength;
	minHeight?: RuntimeLength;
	maxHeight?: RuntimeLength;
	padding?: number;
	gap?: number;
	/**
	 * Opacity ranges from 0 to 1. The type cannot express the upper bound, so a runtime clamp handles
	 * it.
	 */
	opacity?: number;
	backgroundColor?: RuntimeColor;
	borderRadius?: number;
	justify?: RuntimeJustify;
	align?: RuntimeAlign;
	grow?: number;
	/**
	 * This axis was missing for a while. Whether content could shrink was set entirely by each
	 * renderer's default, and the defaults differed (CSS uses 1, Yoga uses 0). The same work squeezed
	 * vertically on the web, so its scroll disappeared, and a long sentence in a row was cut off on
	 * native. Both renderers now shrink only row children by default. This prop lets creators override
	 * that default. `0` means does not shrink, which differs from not writing a value: an unwritten
	 * value inherits the parent's main-axis default. Negative values are not accepted.
	 */
	shrink?: number;
	/**
	 * Horizontal offset in density-independent units. Absent means `0`. The value is a number, not a
	 * string such as `translateX(8px)`. A string brings a grammar (units, function lists, order,
	 * matrix) whose owner is the browser. With numeric axes the order is fixed by the renderer, so
	 * both platforms use the same order. The move does not change layout. It only changes where the
	 * node is drawn, so neighbors are not pushed. The intermediate states of a transition therefore
	 * match on both platforms, which layout axes do not.
	 */
	translateX?: number;
	translateY?: number;
	/**
	 * Scale factor. Absent means `1`. Negative values are not accepted, since flipping is not part of
	 * this vocabulary. The center is always the node's center. `transformOrigin` is not exposed
	 * because its coordinate system differs by platform. Fixing one default lets both renderers
	 * produce the same picture.
	 */
	scale?: number;
}

interface RuntimeTextEntry extends RuntimeTransitionable {
	value: string;
	placeholder?: string;
	disabled?: boolean;
	/** Called after the user edits. It receives the whole text after the change, not a delta. */
	onChangeText?: (value: string) => void | Promise<void>;
	style?: RuntimeStyle;
	textStyle?: RuntimeTextStyle;
	/**
	 * Handle that moves focus for this input. Must come from `useTextEntryController()`. It is not a
	 * ref: no `current`, no selection, no native handle. It opens only `focus()` and `blur()`.
	 */
	controller?: RuntimeTextEntryController;
}

interface RuntimeTextEntryController {
	/** Gives focus here. Does nothing for an inactive input. */
	focus(): void;
	/** Removes focus. Does nothing if focus is already elsewhere. */
	blur(): void;
}

interface RuntimeTextStyle {
	color?: RuntimeColor;
	fontSize?: number;
	fontWeight?: "regular" | "medium" | "bold";
	align?: "start" | "center" | "end";
	lines?: number;
	opacity?: number;
}

interface RuntimeTransition {
	/**
	 * Duration in milliseconds; absent means 200. `0` means no transition, and the host assigns the
	 * value immediately. Negative, NaN, and Infinity are rejected rather than silently clamped, the
	 * same decision `volume` makes.
	 */
	duration?: number;
	easing?: RuntimeEasing;
}

interface RuntimeTransitionable {
	/**
	 * No transition means the value changes immediately. The first render never animates: having the
	 * prop does not make entry an animation, since entering and leaving are not part of this design
	 * yet. Motion happens only when the value of an already-rendered node changes.
	 */
	transition?: RuntimeTransition;
}

interface ScreenProps extends RuntimeChildren {
	/** Background of the whole screen. It extends beyond the safe area. */
	background?: RuntimeColor;
}

interface ScrollViewProps
	extends RuntimeChildren,
		RuntimeTransitionable {
	style?: RuntimeStyle;
	horizontal?: boolean;
	/**
	 * Handle that moves this scroll. Must come from `useScrollController()`.
	 *
	 * Neither a DOM element nor an RN ref belongs here. The value is an opaque controller issued by
	 * the host, and its internal integer cannot be named by the author (see the control.ts header). A
	 * controller binds to one live node at a time. Passing the same controller to two nodes rejects
	 * that render with `runtime_host_control_already_bound`.
	 */
	controller?: RuntimeScrollController;
}

interface StackProps extends RuntimeChildren, RuntimeTransitionable {
	gap?: number;
	style?: RuntimeStyle;
}

interface StoryStateDefinition<T> {
	/**
	 * Brand of this lifetime. The type-level brand is what keeps it distinct from persistent
	 * definitions.
	 */
	readonly [RUNTIME_STORY_STATE]: true;
	readonly key: string;
	readonly version: number;
	readonly initial: T;
	readonly migrate: StoryStateMigration<T> | null;
}

interface TextInputProps extends RuntimeTextEntry {
	/**
	 * Confirmed in a single-line input (Enter on web, Done on native). It is not called during IME
	 * composition: Korean, Japanese and Chinese input use Enter to confirm characters before
	 * composition ends, and treating that as a submit would send the in-progress text. The platform
	 * adapter makes that judgment; this contract only states the result.
	 */
	onSubmit?: () => void | Promise<void>;
}

interface TextProps extends RuntimeChildren {
	style?: RuntimeTextStyle;
}

interface ViewProps extends RuntimeChildren, RuntimeTransitionable {
	style?: RuntimeStyle;
}

function color<S extends string>(
	value: S & ValidHexColor<S>,
): RuntimeColor;

function isPersistentStateDefinition(
	value: unknown,
): value is PersistentStateDefinition<unknown>;

function isRuntimeHostComponent(
	value: unknown,
): value is RuntimeHostComponent<unknown>;

function isStoryStateDefinition(
	value: unknown,
): value is StoryStateDefinition<unknown>;

function useCallback<T extends (...args: never[]) => unknown>(
	callback: T,
	deps?: readonly unknown[],
): T;

function useEffect(
	// biome-ignore lint/suspicious/noConfusingVoidType: the effect gives back a cleanup function or nothing; only this type expresses both.
	effect: () => void | RuntimeCleanup,
	deps?: readonly unknown[],
): void;

function useReducer<S, A>(
	reducer: (state: S, action: A) => S,
	initial: S,
): [S, (action: A) => void];
